  display: block; /* override fieldset legend quirk */
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 0.35rem;
  line-height: 1.4;
  width: 100%;
}

.question__help {
  font-size: 0.83rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
