.option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--check-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.7rem 1rem;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
