.result__score {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--accent);
  line-height: 1;
}

.result__label {
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: 0.4rem;
}

.result__detail {
  margin-top: 1rem;
  font-size: 0.9rem;
  color: var(--text);
}

.result__correct { color: var(--success); font-weight: 600; }
.result__wrong   { color: var(--error);   font-weight: 600; }

