*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:           #0f1117;
  --surface:      #1a1d27;
  --surface-hi:   #23263a;
  --border:       #2e3250;
  --border-focus: #6c7fff;
  --accent:       #6c7fff;
  --accent-hover: #8b9aff;
  --text:         #e2e4f0;
  --text-muted:   #8b8fa8;
  --check-bg:     #252840;
  --check-hover:  #2e3258;
  --success:      #3ecf8e;
  --error:        #f06b6b;
  --radius:       10px;
  --transition:   0.18s ease;
}

html { font-size: 16px; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 2.5rem 1rem 4rem;
}

/* ── Quiz shell ─────────────────────────────────────────────── */
.quiz {
  width: 100%;
  max-width: 680px;
}

.quiz__header {
  margin-bottom: 2.25rem;
  text-align: center;
}

.quiz__badge {
  display: inline-block;
  background: #1e2240;
  border: 1px solid var(--border);
  color: var(--accent);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.3rem 0.75rem;
  border-radius: 20px;
  margin-bottom: 0.75rem;
}

.quiz__title {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}

.quiz__subtitle {
  margin-top: 0.4rem;
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* ── Question progress ──────────────────────────────────────── */
.quiz__progress {
  display: flex;
  gap: 0.4rem;
  margin-bottom: 1.75rem;
}

.quiz__progress-pip {
  flex: 1;
  height: 4px;
  background: var(--border);
  border-radius: 4px;
  transition: background var(--transition);
}

.quiz__progress-pip.active { background: var(--accent); }

/* ── form-field (question card) ─────────────────────────────── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem 1.75rem;
  margin-bottom: 1.25rem;
  transition: border-color var(--transition);
}

.form-field:focus-within { border-color: var(--border-focus); }

/* fieldset resets */
.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.question__number {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.35rem;
}

.question__legend {
  display: block; /* override fieldset legend quirk */
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 0.35rem;
  line-height: 1.4;
  width: 100%;
}

.question__help {
  font-size: 0.83rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

/* ── Checkbox options ───────────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  margin-top: 0.75rem;
}

.option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--check-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.7rem 1rem;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  user-select: none;
}

.option:hover {
  background: var(--check-hover);
  border-color: #3e4470;
}

/* hide native checkbox visually but keep it accessible */
.option__input {
  appearance: none;
  -webkit-appearance: none;
  width: 1.1rem;
  height: 1.1rem;
  min-width: 1.1rem;
  border: 2px solid var(--border-focus);
  border-radius: 4px;
  background: transparent;
  cursor: pointer;
  position: relative;
  transition: background var(--transition), border-color var(--transition);
  outline: none;
}

.option__input:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.option__input:checked {
  background: var(--accent);
  border-color: var(--accent);
}

.option__input:checked::after {
  content: "";
  position: absolute;
  top: 1px;
  left: 4px;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

/* checked state — highlight the whole row */
.option:has(.option__input:checked) {
  background: #252850;
  border-color: var(--accent);
}

.option__label {
  font-size: 0.95rem;
  color: var(--text);
  cursor: pointer;
  flex: 1;
}

/* ── Validation feedback ────────────────────────────────────── */
.form-field[data-valid="false"] { border-color: var(--error); }
.form-field[data-valid="false"] .question__legend { color: var(--error); }

.field-error {
  font-size: 0.8rem;
  color: var(--error);
  margin-top: 0.6rem;
  display: none;
}

.form-field[data-valid="false"] .field-error { display: block; }

/* ── Submit button ──────────────────────────────────────────── */
.quiz__footer {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.5rem;
}

.btn-submit {
  background: var(--accent);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  padding: 0.7rem 1.8rem;
  cursor: pointer;
  transition: background var(--transition), transform 0.1s ease, box-shadow var(--transition);
  box-shadow: 0 0 0 0 transparent;
}

.btn-submit:hover {
  background: var(--accent-hover);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.btn-submit:active { transform: scale(0.98); }

/* ── Result banner ──────────────────────────────────────────── */
.quiz__result {
  display: none;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem 1.75rem;
  margin-top: 1.25rem;
  text-align: center;
}

.quiz__result.visible { display: block; }

.result__score {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--accent);
  line-height: 1;
}

.result__label {
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: 0.4rem;
}

.result__detail {
  margin-top: 1rem;
  font-size: 0.9rem;
  color: var(--text);
}

.result__correct { color: var(--success); font-weight: 600; }
.result__wrong   { color: var(--error);   font-weight: 600; }

/* ── Responsive ─────────────────────────────────────────────── */
@media (max-width: 480px) {
  .form-field { padding: 1.1rem 1rem; }
  .option      { padding: 0.6rem 0.75rem; }
}
