  wrapper.htmlFor = id;

  const input = document.createElement("input");
  input.type      = "checkbox";
  input.id        = id;
  input.name      = id.slice(0, 2); // group by question
  input.className = "option__input";
  input.setAttribute("value", id);

  const span = document.createElement("span");
  span.className = "option__label";
  span.textContent = label;

  wrapper.append(input, span);
  return wrapper;
}

/** Creates a full question card (form-field) */
function createQuestion({ id, number, text, help, options }) {
  const card = document.createElement("div");
  card.className = "form-field";
  card.dataset.question = id;

  const fieldset = document.createElement("fieldset");

  // Accessible legend
  const numEl = document.createElement("p");
  numEl.className = "question__number";
  numEl.setAttribute("aria-hidden", "true");
  numEl.textContent = number;

  const legend = document.createElement("legend");
  legend.className = "question__legend";
  legend.textContent = text;

  fieldset.append(numEl, legend);

  // Optional help text
  if (help) {
    const helpEl = document.createElement("p");
    helpEl.className = "question__help";
    helpEl.id        = `${id}-help`;
    helpEl.textContent = help;
    fieldset.append(helpEl);
    fieldset.setAttribute("aria-describedby", helpEl.id);
