/** Creates the progress pip bar */
function createProgress(count) {
  const bar = document.createElement("div");
  bar.className       = "quiz__progress";
  bar.setAttribute("role", "presentation");
  for (let i = 0; i < count; i++) {
    const pip = document.createElement("div");
    pip.className = "quiz__progress-pip active";
    bar.append(pip);
  }
  return bar;
}

/* ── Quiz component ─────────────────────────────────────────── */
function Quiz({ questions, mountEl }) {
  /* --- render ------------------------------------------------ */
  const root = document.createElement("div");
  root.className = "quiz";
  root.setAttribute("aria-label", "Computer Languages Quiz");

  // Header
  const header = document.createElement("header");
  header.className = "quiz__header";
  header.innerHTML = `
    <p class="quiz__badge">Quiz</p>
    <h1 class="quiz__title">Computer Languages</h1>
    <p class="quiz__subtitle">Select all correct answers for each question, then submit.</p>
  `;

  // Progress
  root.append(header, createProgress(questions.length));

  // Form
  const form = document.createElement("form");
  form.setAttribute("novalidate", "");
  form.setAttribute("aria-label", "Quiz form");

  questions.forEach(q => form.append(createQuestion(q)));

  // Footer with submit
  const footer = document.createElement("div");
  footer.className = "quiz__footer";

  const submitBtn = document.createElement("button");
  submitBtn.type      = "submit";
  submitBtn.className = "btn-submit";
  submitBtn.textContent = "Submit answers";
  footer.append(submitBtn);
  form.append(footer);

  // Result banner
  const resultBanner = document.createElement("div");
  resultBanner.className = "quiz__result";
  resultBanner.setAttribute("role", "status");
  resultBanner.setAttribute("aria-live", "polite");
  resultBanner.id = "quiz-result";

  root.append(form, resultBanner);
