  /** Returns checked option IDs for a question */
  function getChecked(questionId) {
    return [...form.querySelectorAll(`input[value^="${questionId}"]`)]
      .filter(cb => cb.checked)
      .map(cb => cb.value);
  }

  /** Validates a question card; returns true if valid */
  function validateCard(q) {
    const card    = form.querySelector(`[data-question="${q.id}"]`);
    const checked = getChecked(q.id);
    const valid   = checked.length > 0;
    card.dataset.valid = valid ? "true" : "false";
    const errEl = card.querySelector(".field-error");
    if (errEl) {
      errEl.textContent = valid
        ? ""
        : "Please select at least one answer.";
    }
    return valid;
  }

  /** Clears previous validation state when user interacts */
  form.addEventListener("change", ({ target }) => {
    if (target.type !== "checkbox") return;
    const cardEl = target.closest(".form-field");
