    resultBanner.innerHTML = `
      <p class="result__score">${numCorrect}/${questions.length}</p>
      <p class="result__label">questions fully correct</p>
      <p class="result__detail">
        ${results.map((r, i) =>
          `<span class="${r.isCorrect ? "result__correct" : "result__wrong"}">
            Q${i + 1}: ${r.isCorrect ? "✓ Correct" : "✗ Incorrect"}
          </span>`
        ).join("&ensp;·&ensp;")}
      </p>
    `;
    resultBanner.classList.add("visible");
    resultBanner.scrollIntoView({ behavior: "smooth", block: "nearest" });
  });
