+  const root = document.createElement("div");
+  root.className = "quiz";
+  root.setAttribute("aria-label", "Computer Languages Quiz");
+
+  // Header
+  const header = document.createElement("header");
+  header.className = "quiz__header";
+  header.innerHTML = `
+    <p class="quiz__badge">Quiz</p>
+    <h1 class="quiz__title">Computer Languages</h1>
+    <p class="quiz__subtitle">Select all correct answers for each question, then submit.</p>
+  `;
+
+  // Progress
+  root.append(header, createProgress(questions.length));
+
+  // Form
+  const form = document.createElement("form");
+  form.setAttribute("novalidate", "");
+  form.setAttribute("aria-label", "Quiz form");
+
+  questions.forEach(q => form.append(createQuestion(q)));
+
+  // Footer with submit
+  const footer = document.createElement("div");
+  footer.className = "quiz__footer";
+
+  const submitBtn = document.createElement("button");
+  submitBtn.type      = "submit";
+  submitBtn.className = "btn-submit";
+  submitBtn.textContent = "Submit answers";
+  footer.append(submitBtn);
+  form.append(footer);
+
+  // Result banner
+  const resultBanner = document.createElement("div");
+  resultBanner.className = "quiz__result";
+  resultBanner.setAttribute("role", "status");
+  resultBanner.setAttribute("aria-live", "polite");
+  resultBanner.id = "quiz-result";
+
+  root.append(form, resultBanner);
+  mountEl.append(root);
+
+  /* --- behaviour --------------------------------------------- */
+
+  /** Returns checked option IDs for a question */
+  function getChecked(questionId) {
+    return [...form.querySelectorAll(`input[value^="${questionId}"]`)]
+      .filter(cb => cb.checked)
+      .map(cb => cb.value);
+  }
+
+  /** Validates a question card; returns true if valid */
+  function validateCard(q) {
+    const card    = form.querySelector(`[data-question="${q.id}"]`);
+    const checked = getChecked(q.id);
+    const valid   = checked.length > 0;
+    card.dataset.valid = valid ? "true" : "false";
+    const errEl = card.querySelector(".field-error");
+    if (errEl) {
+      errEl.textContent = valid
+        ? ""
+        : "Please select at least one answer.";
+    }
+    return valid;
+  }
+
+  /** Clears previous validation state when user interacts */
+  form.addEventListener("change", ({ target }) => {
+    if (target.type !== "checkbox") return;
+    const cardEl = target.closest(".form-field");
+    if (cardEl) delete cardEl.dataset.valid;
+  });
+
+  /** Scores a question — returns { correct, total } */
+  function scoreQuestion(q) {
+    const correctIds  = q.options.filter(o => o.correct).map(o => o.id);
+    const selectedIds = getChecked(q.id);
+
+    const allCorrectSelected = correctIds.every(id => selectedIds.includes(id));
+    const noWrongSelected    = selectedIds.every(id => correctIds.includes(id));
+    return {
+      isCorrect: allCorrectSelected && noWrongSelected,
+      correctIds,
+      selectedIds,
+    };
+  }
+
+  form.addEventListener("submit", (e) => {
+    e.preventDefault();
+
+    // Validate all questions first
+    let firstInvalidCard = null;
+    let allValid = true;
+    questions.forEach(q => {
+      const valid = validateCard(q);
+      if (!valid) {
+        allValid = false;
+        if (!firstInvalidCard) {
+          firstInvalidCard = form.querySelector(`[data-question="${q.id}"]`);
+        }
+      }
+    });
+
+    if (!allValid) {
+      firstInvalidCard?.querySelector("input")?.focus();
+      return;
+    }
+
+    // Score
+    const results = questions.map(scoreQuestion);
+    const numCorrect = results.filter(r => r.isCorrect).length;
+
+    // Disable inputs after submit
+    form.querySelectorAll("input, button").forEach(el => (el.disabled = true));
+
+    // Render result banner
+    resultBanner.innerHTML = `
+      <p class="result__score">${numCorrect}/${questions.length}</p>
+      <p class="result__label">questions fully correct</p>
+      <p class="result__detail">
+        ${results.map((r, i) =>
+          `<span class="${r.isCorrect ? "result__correct" : "result__wrong"}">
+            Q${i + 1}: ${r.isCorrect ? "✓ Correct" : "✗ Incorrect"}
+          </span>`
+        ).join("&ensp;·&ensp;")}
+      </p>
+    `;
+    resultBanner.classList.add("visible");
+    resultBanner.scrollIntoView({ behavior: "smooth", block: "nearest" });
+  });
+}
+
+/* ── Mount ──────────────────────────────────────────────────── */
+document.addEventListener("DOMContentLoaded", () => {
+  Quiz({
+    questions: QUESTIONS,
+    mountEl:   document.getElementById("app"),
+  });
+});
+
')

